def _span(type_id: int, dims: tuple[int, ...]) -> int:
    elements = 1
    for dim in dims:
        elements *= dim
    block_bytes = {F32: (1, 4), Q5_0: (32, 22), Q4_K: (256, 144), Q6_K: (256, 210)}
    block, byte_count = block_bytes[type_id]
    if elements % block:
        return 0
    return elements // block * byte_count


